module pattern_matcher (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] word0, word1, word2, word3,\n    input wire [7:0] word4, word5, word6, word7,\n    input wire [3:0] len0, len1, len2, len3,\n    input wire [3:0] len4, len5, len6, len7,\n    input wire [7:0] pat0, pat1, pat2, pat3,\n    input wire [7:0] pat4, pat5, pat6, pat7,\n    input wire [3:0] star_pos,\n    input wire [3:0] pattern_len,\n    input wire [3:0] num_words,\n    output reg [7:0] count,\n    output reg done\n);\n\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] CHECK_LEN   = 3'd1;\n    localparam [2:0] CHECK_PRE   = 3'd2;\n    localparam [2:0] CHECK_SUF   = 3'd3;\n    localparam [2:0] COUNT_MATCH = 3'd4;\n    localparam [2:0] NEXT_WORD   = 3'd5;\n    localparam [2:0] DONE_STATE  = 3'd6;\n    \n    reg [2:0] state;\n    reg [3:0] word_idx;\n    reg [3:0] char_idx;\n    reg match_curr;\n    reg [3:0] prefix_len;\n    reg [3:0] suffix_len;\n    reg [3:0] min_len;\n    reg [7:0] curr_word_char;\n    reg [3:0] curr_word_len;\n    reg [7:0] curr_pat_char;\n    reg [7:0] word_ptr[0:7];\n    reg [7:0] pat_ptr[0:7];\n    reg [3:0] len_ptr[0:7];\n    reg [7:0] counter;\n    \n    always @(*) begin\n        word_ptr[0] = word0; word_ptr[1] = word1; word_ptr[2] = word2; word_ptr[3] = word3;\n        word_ptr[4] = word4; word_ptr[5] = word5; word_ptr[6] = word6; word_ptr[7] = word7;\n        pat_ptr[0] = pat0; pat_ptr[1] = pat1; pat_ptr[2] = pat2; pat_ptr[3] = pat3;\n        pat_ptr[4] = pat4; pat_ptr[5] = pat5; pat_ptr[6] = pat6; pat_ptr[7] = pat7;\n        len_ptr[0] = len0; len_ptr[1] = len1; len_ptr[2] = len2; len_ptr[3] = len3;\n        len_ptr[4] = len4; len_ptr[5] = len5; len_ptr[6] = len6; len_ptr[7] = len7;\n        curr_word_char = word_ptr[char_idx];\n        curr_pat_char = pat_ptr[char_idx];\n        curr_word_len = len_ptr[word_idx];\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            count <= 8'd0;\n            done <= 1'b0;\n            word_idx <= 4'd0;\n            char_idx <= 4'd0;\n            match_curr <= 1'b0;\n            prefix_len <= 4'd0;\n            suffix_len <= 4'd0;\n            min_len <= 4'd0;\n            counter <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        prefix_len <= star_pos;\n                        suffix_len <= pattern_len - star_pos - 4'd1;\n                        min_len <= pattern_len - 4'd1;\n                        word_idx <= 4'd0;\n                        count <= 8'd0;\n                        state <= CHECK_LEN;\n                    end\n                end\n                \n                CHECK_LEN: begin\n                    if (word_idx >= num_words) begin\n                        state <= DONE_STATE;\n                    end else if (curr_word_len >= min_len) begin\n                        char_idx <= 4'd0;\n                        match_curr <= 1'b1;\n                        state <= CHECK_PRE;\n                    end else begin\n                        word_idx <= word_idx + 4'd1;\n                    end\n                end\n                \n                CHECK_PRE: begin\n                    if (char_idx >= prefix_len) begin\n                        if (suffix_len == 4'd0) begin\n                            state <= COUNT_MATCH;\n                        end else begin\n                            char_idx <= curr_word_len - suffix_len;\n                            state <= CHECK_SUF;\n                        end\n                    end else begin\n                        if (curr_word_char != curr_pat_char) begin\n                            match_curr <= 1'b0;\n                            state <= NEXT_WORD;\n                        end else begin\n                            char_idx <= char_idx + 4'd1;\n                        end\n                    end\n                end\n                \n                CHECK_SUF: begin\n                    if (char_idx >= curr_word_len) begin\n                        state <= COUNT_MATCH;\n                    end else begin\n                        if (curr_word_char != pat_ptr[prefix_len + 4'd1 + (char_idx - (curr_word_len - suffix_len))]) begin\n                            match_curr <= 1'b0;\n                            state <= NEXT_WORD;\n                        end else begin\n                            char_idx <= char_idx + 4'd1;\n                        end\n                    end\n                end\n                \n                COUNT_MATCH: begin\n                    count <= count + match_curr;\n                    state <= NEXT_WORD;\n                end\n                \n                NEXT_WORD: begin\n                    word_idx <= word_idx + 4'd1;\n                    state <= CHECK_LEN;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule